    "explanation": "메커니즘 및 로직 설명",
    "permit": "허용",
    "deny": "거부 (Deny)",
    "explanation_iptables_filter": "iptables는 기본적으로 'filter' 테이블을 사용합니다. 'INPUT'은 로컬 시스템으로 들어오는 패킷을 처리하고, 'FORWARD'는 시스템을 통과하는(라우팅) 트래픽을 처리합니다. 보안을 위해 상태 기반 규칙(conntrack) 사용을 권장합니다.",
    "explanation_masquerade": "Masquerading은 Dynamic SNAT의 일종입니다. 소스 IP를 나가는 인터페이스({iface})의 IP로 대체합니다. 사설 LAN에서 유동 공인 IP를 통해 인터넷에 접속할 때 사용됩니다.",
    "explanation_snat": "Static SNAT (Source NAT)는 소스 IP를 고정된 주소({target})로 대체합니다. 게이트웨이에 여러 개의 고정 IP가 있을 때 사용됩니다.",
    "explanation_dnat": "DNAT (Destination NAT) 또는 포트 포워딩은 들어오는 패킷의 대상 IP/포트를 수정합니다. 이를 통해 외부 사용자가 사설 네트워크 내부의 서버에 접속할 수 있습니다.",
    "explanation_nftables": "nftables는 iptables의 최신 대체 기술입니다. 단일 'nft' 도구를 사용하며 IPv4와 IPv6를 모두 처리하는 'inet' 테이블을 지원합니다. NAT 규칙은 보통 prerouting 시 우선순위 -100, postrouting 시 100으로 'nat' 테이블에 훅으로 추가됩니다.",
    "explanation_default": "이 설정은 선택한 플랫폼에 필요한 구문을 생성합니다. 대부분의 방화벽 정책은 위에서 아래로 순차적으로 실행됩니다.",
    "generate": "규칙 생성",
