  "ipv6_trans": {
    "title": "전환 기술 치트 시트",
    "dual_stack": "듀얼 스택",
    "dual_stack_desc": "노드가 IPv4와 IPv6를 동시에 실행합니다. 가장 일반적이고 선호되는 방법입니다. 두 프로토콜 스택 모두에 글로벌 주소가 필요합니다.",
    "nat64": "NAT64 / DNS64",
    "nat64_desc": "변환을 통해 IPv6 전용 클라이언트가 IPv4 전용 서버와 통신할 수 있도록 합니다. DNS64는 프리픽스를 사용하여 A 레코드에서 AAAA 레코드를 합성합니다.",
    "xlat": "464XLAT",
    "xlat_desc": "클라이언트 측(CLAT) 및 공급자 측(PLAT) 변환을 결합합니다. 레거시 IPv4 전용 애플리케이션을 지원하기 위해 모바일 네트워크에서 흔히 사용됩니다.",
    "dslite": "DS-Lite",
    "dslite_desc": "Dual-Stack Lite. IPv6 전용 코어에서 IPv4 터널링(RFC 6333). NAT를 고객 장치에서 통신사(AFTR)로 이동합니다.",
    "mape": "MAP-E / MAP-T",
    "mape_desc": "Mapping of Address and Port. 대규모 IPv6 사용자들 사이에 IPv4 포트 범위를 분산시키는 스테이트리스 전환 메커니즘입니다.",
    "gre": "6in4 / GRE",
    "gre_desc": "IPv4 헤더(Proto 41) 내부에 IPv6 패킷을 정적으로 터널링합니다. 주로 홈 랩을 터널 브로커에 연결하는 데 사용됩니다.",
    "comparison": "전환 메커니즘 비교",
    "mechanism": "메커니즘",
    "key_use_case": "주요 사용 사례",
    "flow_nat64": "흐름 시각화: NAT64",
    "flow_dslite": "흐름 시각화: DS-Lite",
    "term_ref": "용어 참조",
    "status_stateful": "Stateful",
    "status_stateless": "Stateless",
    "status_static": "Static",
    "translation_label": "변환",
    "use_case_dual_stack": "모든 현대적 네트워크를 위한 선호 표준",
    "use_case_nat64": "IPv6 전용 데이터 센터 및 공용 WiFi",
    "use_case_xlat": "IPv6 전용 통신사의 모바일(Android/iOS)",
    "use_case_dslite": "IPv6 코어 백본을 사용하는 케이블/FTTH ISP",
    "use_case_mape": "대규모 ISP 인프라 (일본, 유럽)",
    "use_case_gre": "IPv4 전용 WAN에서 IPv6가 필요한 레거시 사이트",
    "flow_synthesized": "(합성됨)",
    "flow_pool_v4": "(풀 IPv4)",
    "flow_actual_v4": "(실제 IPv4)",
    "flow_decaps_nat": "코어에서 캡슐화 해제 및 NAT",
    "flow_shared_pool": "(공유 ISP 공인 IP 풀)",
    "b4_desc": "고객 측 DS-Lite 요소. IPv4 패킷을 AFTR로 향하는 IPv6 터널로 캡슐화합니다. CPE나 홈 라우터에 상주합니다.",
    "aftr_desc": "공급자 측 DS-Lite 요소. B4에서 터널링된 IPv4 트래픽을 수신하여 캡슐화를 해제하고 IPv4 인터넷으로 NAT를 수행합니다.",
    "clat_plat_desc": "CLAT(Customer-side transLATor)는 장치에서 실행되며 IPv4를 IPv6로 변환합니다. PLAT(Provider-side transLATor)는 통신사의 NAT64 게이트웨이입니다. 둘이 합쳐 464XLAT를 구성합니다.",
    "rfc6052_desc": "IPv4/IPv6 주소 변환(NAT64, MAP-T)에 사용되는 잘 알려진 프리픽스 64:ff9b::/96입니다. 주소 제품군 간의 알고리즘 매핑을 위해 RFC 6052에 정의되어 있습니다."
  },
