    "mpls_title": "MPLS — Multi-Protocol Label Switching",
    "mpls_desc": "MPLS는 Layer 2와 Layer 3 헤더 사이에 32비트 라벨을 삽입하여 \"Layer 2.5\" shim을 생성합니다. 패킷은 전체 IP 조회를 수행하는 대신 각 LSR (Label Switching Router)에서 라벨을 교체하여 전달되므로 빠른 포워딩, 트래픽 엔지니어링 및 VPN이 가능합니다.",
