    "label_desc": "20비트 포워딩 라벨. 0–15 값은 예약되어 있습니다. 라우터는 각 LSR 홉에서 이 값을 교체(swap)하거나 제거(pop)합니다.",
    "tc_desc": "Traffic Class (이전의 EXP). QoS/CoS 마킹을 위한 3비트 — MPLS 도메인 내부의 DSCP 또는 큐 우선순위에 매핑됩니다.",
    "s_desc": "Bottom-of-Stack 비트. 가장 안쪽 라벨에서 1로 설정됩니다. S=1이면 다음 헤더는 원본 IP 패킷입니다.",
    "ttl_desc": "Time To Live. 각 LSR에서 감소하며 IP TTL과 동일한 역할을 합니다. 라벨 루프를 방지합니다. 유입 시 IP TTL에서 복사됩니다.",
