    "label_ops": "라벨 작업",
    "push_desc": "MPLS 도메인에 진입하는 라벨 없는 IP 패킷에 하나 이상의 라벨을 추가합니다.",
    "swap_desc": "최상위 라벨을 새로운 발신 라벨로 교체하고 패킷을 전달합니다.",
    "pop_desc": "최상위 라벨을 제거합니다. PHP (Penultimate Hop Popping)는 유출 전 한 홉 앞에서 제거합니다.",
    "php_desc": "유출 전 마지막 LSR이 transport 라벨을 제거하여 유출 LER의 부하를 줄입니다. Implicit-null 라벨 (3)이 PHP를 신호합니다.",
    "reserved_values": "예약된 라벨 값 (0–15)",
    "ldp_protocols": "라벨 배포 프로토콜",
