    "control_logic": "제어 로직",
    "ptp_title": "PTP 참조 (Precision Time Protocol)",
    "ptp_desc": "PTP는 IPFM 패브릭의 심장박동과 같습니다. 모든 A/V 노드가 위상을 유지할 수 있도록 마이크로초 미만의 정밀한 동기화를 제공합니다.",
    "node_roles": "노드 역할:",
    "gm_title": "Grandmaster (GM)",
    "gm_desc": "참조 클록 (GPS 동기화).",
    "bc_title": "Boundary Clock (BC)",
    "bc_desc": "Nexus 스위치 역할. PTP를 종단하고 재생성하여 지터 누적을 방지합니다.",
    "slave_title": "Slave / Follower",
    "slave_desc": "BC에 동기화되는 엔드 노드 (카메라, 믹서 등).",
    "key_params": "주요 파라미터:",
    "domain_desc": "Domain: 논리적 격리 그룹 (SMPTE 2059-2는 domain 0 사용)",
    "priority_desc": "Priority 1/2: BMCA (Best Master Clock Algorithm) 제어",
    "intervals_desc": "Announce / Sync 간격: PTP 메시지 빈도",
    "nbm_title": "Network Bandwidth Manager (NBM)",
    "nbm_desc": "NBM은 \"SDI와 유사한\" 결정론적 동작을 보장하는 Nexus 9000용 특화 멀티캐스트 엔진입니다.",
    "core_benefits": "핵심 이점:",
    "zero_loss": "Zero Packet Loss:",
    "zero_loss_desc": "엄격한 대역폭 수용 제어.",
    "active_mode": "Active 모드:",
    "active_mode_desc": "구성된 플로우 정책 값(실제 트래픽이 아님)을 기반으로 대역폭 수용 제어. 스위치는 NDFC 플로우 정책에 따라 대역폭을 예약합니다.",
    "passive_mode": "Passive 모드:",
    "passive_mode_desc": "글로벌 경로 예약을 위해 외부 컨트롤러(NDFC/DCNM/ND)에 의해 플로우 관리가 오케스트레이션됩니다.",
    "ops_constraints": "운영 제약 사항:",
    "nbm_constraints": "특정 Nexus 9000 Cloud Scale ASIC이 필요합니다. 플로우 폴리싱은 \"rogue\" 멀티캐스트 소스가 범람하는 것을 방지합니다.",
    "ptp_hierarchy": "PTP 타이밍 계층 (BMCA)",
    "ptp_hierarchy_desc": "PTP 계층은 Best Master Clock Algorithm (BMCA)에 의해 결정됩니다. 낮은 Priority 값이 GM 선출에서 승리합니다. 각 Boundary Clock은 PTP를 종단하고 재생성하여 다운스트림 장치를 업스트림 지터로부터 격리합니다. IPFM에서 GM(전용 GPS 장비)은 Spine 레이어에 {directly} 연결되며, 다이어그램은 이들 상단에 위치한 GM을 올바르게 보여줍니다.",
    "gm_gps": "GM — Grandmaster (GPS)",
