    "spine_hint": "priority1: 128 • GM으로부터 PTP 수신 종단 • 모든 Leaf에 시간 제공",
    "slave_port": "Slave 포트",
    "leaf_bc": "Leaf — Boundary Clock",
    "leaf_hint": "priority1: 128 • 엔드포인트에 대해 Master 역할",
    "master_ports": "Master 포트",
    "endpoints": "엔드포인트 (Ordinary Clock Slaves)",
    "media_nodes_a": "카메라, 믹서, 인코더 (ST 2110)",
    "media_nodes_b": "모니터, 디코더, 오디오 (AES67)",
    "sync_flow": "동기화 흐름 방향",
    "dual_plane_hint": "ST 2022-7 심리스 보호를 위해 Dual-plane A/B 패브릭 필요",
    "healthy_sync": "Master와의 오프셋 < 100ns = 정상 동기화 상태",
    "clos_title": "CLOS Dual-Plane 패브릭 (ST 2022-7 Redundancy)",
    "clos_desc": "운영 IPFM 패브릭은 두 개의 독립적인 spine-leaf 플레인(A & B)을 배포하며, 각 플레인은 평면 내 복원력을 위해 {double_spine} 설계를 가집니다. 각 ST 2110 플로우는 두 플레인을 동시에 횡단합니다. Spine이나 Leaf 장애 시에도 수신기는 Zero Packet Loss와 함께 살아남은 플레인으로부터 심리스하게 서비스를 계속합니다.",
