    "type_prefix": "유형 ",
    "polarity_desc_A": "다이렉트 케이블. A단은 키-업(key-up), B단은 키-다운(key-down). B단의 커넥터 뒤집기로 인해 섬유 열이 반전됩니다. A단의 n번 위치는 B단의 (총합+1−n)번 위치에 도달합니다.",
    "polarity_desc_B": "반전 케이블 (키-업 대 키-업). A단의 n번 위치가 B단의 n번 위치로 직접 매핑됩니다. 열 반전을 상쇄하기 위해 내부적으로 한쪽 커넥터를 뒤집어 제작되었습니다.",
    "polarity_desc_C": "인접 쌍 교체 케이블. A단은 키-업, B단은 키-다운. 연속된 섬유 쌍이 커넥터 반전 전에 교체됩니다. 카세트 모듈에서 쌍 재정렬이 필요한 경우 사용됩니다.",
