    "note_pins_label": "수형 vs 암형",
    "note_pins": "수형 커넥터에는 가이드 핀이 있고, 암형 커넥터에는 가이드 핀 구멍이 있습니다. 트랜시버는 암형 MPO를 사용하며, 패치 케이블은 일반적으로 수형-암형 구성을 가집니다.",
