    "sysctl_title": "Linux TCP 튜닝 (sysctl)",
    "sysctl_subtitle": "경로 매개변수에 맞춰 Linux TCP 버퍼와 혼잡 제어를 튜닝하기 위한 sysctl 명령을 생성합니다.",
    "sysctl_algo": "혼잡 제어 알고리즘",
    "sysctl_apply_hint": "적용 방법: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. 값은 BDP에서 계산됩니다.",
    "ref_title": "알고리즘 참조",
    "ref_reno_desc": "고전적인 AIMD 알고리즘. 슬로우 스타트는 ssthresh까지 RTT마다 cwnd를 2배로 늘립니다. 혼잡 회피는 RTT마다 약 1 세그먼트를 추가합니다. 3개의 중복 ACK 시: ssthresh = cwnd/2, cwnd = ssthresh. 타임아웃 시: cwnd = 1 MSS. 공정하지만 손실 후 고 BDP 경로의 이용률이 낮습니다.",
    "ref_cubic_desc": "Linux 기본값. 3차 함수 W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7)를 사용합니다. 손실 후 cwnd는 W_max의 70%로 떨어지고 이후 오목-볼록 곡선을 통해 성장합니다. 롱-팻 네트워크에서 Reno보다 공격적입니다. K = (W_max * 0.3 / C)^(1/3).",
    "ref_bbr_desc": "Google의 모델 기반 알고리즘. 손실을 신호로 사용하는 대신 병목 대역폭과 최소 RTT를 추정합니다. 단계: Startup (2.89배 이득), Drain, ProbeBW (8단계 이득 주기: 1.25/0.75/1...), ProbeRTT (약 10초마다 4 세그먼트). 손실이 있어도 전체 처리량을 달성합니다.",
    "phase_startup": "스타트업",
