    "download_sh": ".sh 다운로드",
    "download_yaml": ".yml 다운로드",
    "quick_verify": "빠른 확인:",
    "overlay_note": "오버레이 네트워크에는 Docker Swarm (docker swarm init)이 필요합니다. 독립형 컨테이너를 허용하려면 --attachable을 사용하세요.",
    "macvlan_note": "MACVLAN은 컨테이너당 실제 MAC을 할당합니다. 상위 NIC에서 promiscuous 모드가 필요합니다. 컨테이너는 물리적 네트워크와 직접 통신할 수 있습니다.",
    "ipvlan_note": "IPvLAN은 상위 MAC을 공유합니다. L2 모드는 동일한 브로드캐스트 도메인을 사용하고, L3 모드는 각 컨테이너 서브넷을 별도로 라우팅합니다 (ARP 플러딩 없음).",
    "cni_desc": "Kubernetes CNI 플러그인은 포드 네트워킹을 처리합니다. Docker 네트워크와의 주요 차이점: 포드당 IP, 네트워크 정책, 기본적으로 NAT 없음.",
    "cni_model": "데이터 평면",
    "cni_policy": "네트워크 정책",
    "cni_perf": "성능",
    "cni_enc": "암호화",
    "cni_usecase": "최적 용도",
    "cni_vs_docker": "Docker 네트워크는 호스트 범위(bridge) 또는 스웜 범위(overlay)입니다. K8s CNI 플러그인은 모든 포드가 NAT 없이 라우팅 가능한 IP를 갖는 클러스터 전체의 플랫 포드 네트워킹을 제공합니다.",
    "desc_bridge": "Docker 호스트의 소프트웨어 브리지 — 기본 모드입니다. 컨테이너는 서브넷을 공유하고 외부와 NAT를 통해 통신합니다. 단일 호스트 애플리케이션에 적합합니다.",
    "desc_overlay": "VXLAN 캡슐화를 사용하는 다중 호스트 오버레이 — Docker Swarm이 필요합니다. 서로 다른 호스트의 컨테이너가 동일한 L2 세그먼트에 나타납니다.",
    "desc_macvlan": "각 컨테이너는 상위 NIC의 L2 세그먼트에서 직접 고유한 MAC 및 IP를 얻습니다. NAT 및 브리지가 없습니다. 직접 L2 액세스가 필요한 레거시 앱에 적합합니다.",
    "desc_ipvlan": "MACVLAN과 유사하지만 모든 컨테이너가 상위 MAC을 공유합니다. L3 모드는 컨테이너 IP를 라우팅하여 대규모 배포에서 ARP 스톰 위험을 제거합니다.",
    "desc_host": "컨테이너가 호스트 네트워크 네임스페이스를 직접 공유합니다 — 격리 없음, 최대 성능. 모니터링 에이전트와 같이 지연 시간에 민감한 워크로드에 사용하세요.",
    "desc_none": "루프백을 제외한 네트워크 인터페이스가 없습니다. 완전한 네트워크 격리. 컨테이너에 네트워크 액세스가 필요하지 않은 경우 사용하세요.",
