    "proto_scp_notes": "Secure Copy 프로토콜. SSH 암호화 때문에 구형 네트워크 장치에서 CPU 오버헤드가 높습니다.",
    "proto_sftp_notes": "SSH 파일 전송 프로토콜. 표준 보안 전송 방식. 프로토콜 오버헤드로 인해 SCP보다 약간 느립니다.",
    "proto_tftp_notes": "Trivial FTP. 잠금 단계(lockstep) 블록 단위 전송. 지연 시간에 크게 제한됩니다. 표준 블록 크기에서는 약 1.5 - 3.5 Mbps로 제한됩니다.",
    "proto_ftp_notes": "파일 전송 프로토콜. 오버헤드가 매우 낮고 빠르지만 암호화되지 않습니다. 자격 증명이 평문으로 전송됩니다.",
    "proto_http_notes": "하이퍼텍스트 전송 프로토콜. 빠르고 오버헤드가 낮습니다. 로컬 스테이징 서버에 매우 적합합니다.",
    "proto_https_notes": "HTTP 보안. 최신 ZTP / 클라우드 다운로드의 표준. 중간 수준의 암호화 오버헤드.",
    "plat_iosxe": "Cisco IOS / IOS-XE",
    "plat_iosxr": "Cisco IOS-XR",
    "plat_nxos": "Cisco NX-OS",
    "plat_junos": "Juniper Junos",
    "plat_eos": "Arista EOS",
    "plat_fortios": "Fortinet FortiOS",
    "plat_panos": "Palo Alto PAN-OS",
    "plat_linux": "Linux (curl / wget / scp)",
    "plat_f5": "F5 BIG-IP",
    "plat_huawei": "Huawei VRP",
    "plat_iosxe_notes": "\"show flash:\" 명령으로 플래시 파일 시스템에 충분한 여유 공간이 있는지 확인하십시오. SCP를 사용하는 경우 서버에 \"ip scp server enable\"을 설정하거나 장치에서 SSH 라우팅을 활성화해야 합니다.",
    "plat_iosxr_notes": "IOS-XR 파일 시스템은 flash: 대신 disk0: 또는 disk1:을 사용합니다. XR의 SCP/SFTP 명령은 사용자 비밀번호를 대화형으로 묻습니다. 라우팅 컨텍스트(VRF)는 전역으로 구성할 수 있습니다.",
    "plat_nxos_notes": "NX-OS는 기본적으로 bootflash:를 사용합니다. \"dir bootflash:\"로 파일 시스템 공간을 확인하십시오. VRF는 서버에 대한 IP 도달성이 있어야 합니다. 기본 라우팅 또는 관리 VRF를 확인하십시오.",
    "plat_junos_notes": "Junos에서 파일 복사본은 /var/tmp/ 또는 /var/db/config/에 저장됩니다. \"show system storage\"로 디스크 공간을 확인하십시오. TFTP 전송에는 Junos 라우팅 프로토콜 구성 또는 routing-instance 키워드 사용이 필요할 수 있습니다.",
    "plat_eos_notes": "Arista 장치는 flash:를 사용합니다. \"dir flash:\"로 확인하십시오. 높은 처리량을 위해 Arista는 고도로 최적화된 네이티브 HTTP/HTTPS 복사를 지원합니다.",
    "plat_fortios_notes": "FortiOS TFTP 복원은 부팅 이미지를 교체하고 장치를 자동으로 재부팅합니다. 주의해서 사용하십시오. 항상 사전에 구성 파일을 저장하십시오.",
    "plat_panos_notes": "Palo Alto PAN-OS에서 소프트웨어 가져오기 명령을 실행하려면 명시적인 CLI 관리자 권한이 필요합니다. 소프트웨어는 Palo Alto 공식 지원 업데이트에서 직접 다운로드할 수도 있습니다.",
    "plat_linux_notes": "대상 디렉터리의 읽기/쓰기 권한을 확인하십시오. 클라이언트(scp, curl)가 설치되어 있는지 확인하십시오. curl/wget을 통한 HTTP/HTTPS 전송은 높은 병렬화가 가능합니다.",
    "plat_f5_notes": "bigstart 프로세스와 F5 관리 경로 권한을 확인하십시오. 대상 폴더 /shared/images/는 F5 ISO 파일의 기본 위치입니다.",
