    "explanation_title": "NAT vs. PAT 이해하기",
    "explanation_intro": "네트워크 주소 변환(NAT) 및 포트 주소 변환(PAT)은 한 IP 주소 공간을 다른 공간으로 매핑하는 기술로, 주로 제한된 공용 IPv4 주소를 보존하거나 서브넷 충돌을 해결하는 데 사용됩니다.",
    "nat_expl_title": "1. NAT란 무엇인가요?",
    "nat_expl_desc": "NAT는 IP 주소를 1대1로 변환합니다. 정적(사설 IP 하나를 공용 IP 하나에 영구적으로 매핑, 외부 서비스 서버에 이상적) 또는 동적(요청 시 풀에서 사설 호스트에 공용 IP 할당. 모든 공용 IP가 할당되면 IP가 반환될 때까지 다음 호스트는 차단됨)일 수 있습니다. 포트 번호는 수정되지 않습니다.",
    "pat_expl_title": "2. PAT (NAT Overload)란 무엇인가요?",
    "pat_expl_desc": "PAT(또는 포트 주소 변환 / NAT Overload)는 다대일(N대1) 방식으로 IP 주소와 소스 포트 번호를 모두 변환합니다. 고유한 소스 포트를 할당하여 여러 사설 호스트가 단일 공용 IP 주소를 공유합니다(예: 192.168.1.10:5000 및 192.168.1.11:5000이 203.0.113.10:1024 및 203.0.113.10:1025로 매핑됨). 이는 가정용 라우터 및 기업 인터넷 접속의 표준 방식입니다.",
    "comparison_table_title": "비교 요약",
