    "refid_gps": "GPS 위성 시간 신호",
    "refid_pps": "하드웨어 참조의 초당 펄스 신호",
    "refid_gal": "Galileo GNSS 위성 신호(유럽)",
    "refid_glns": "GLONASS 위성 신호(러시아어)",
