    "refid_rate": "Kiss-o'-Death: 클라이언트가 너무 빠르게 폴링하고 있습니다. — 폴링 간격을 줄입니다.",
    "refid_bcst": "방송 모드 시간 소스",
    "refid_mcst": "멀티캐스트 모드 시간 소스",
    "kod_title": "Kiss-o'-Death(KoD) 패킷",
    "kod_desc": "Kiss-o'-Death 패킷은 오류나 정책 조건을 알리기 위해 NTP 서버에서 전송됩니다. Stratum은 0으로 설정되고 refid는 이유 코드를 인코딩합니다. 클라이언트는 KoD를 존중하고 폴링을 중지하거나 줄여야 합니다.",
    "kod_deny": "액세스 거부됨 - 클라이언트가 ACL에 의해 차단되었습니다.",
    "kod_rstr": "액세스 제한됨 - 클라이언트가 속도가 제한되거나 차단되었습니다.",
